#!/usr/bin/env node
// gen-client-event-kinds.mjs — generate scene3d/client_event_kinds.js from the
// `const CLIENT_EVENT_KIND_*: u32 = N;` declarations in the wasm crate, so JS
// can dispatch on named kinds instead of magic numbers that silently drift
// from Rust.
//
//   node scripts/gen-client-event-kinds.mjs          # (re)write the JS module
//   node scripts/gen-client-event-kinds.mjs --check  # exit 1 if it is stale (CI)

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const SRC = join(ROOT, "apps/holtburger-web/src/lib.rs");
const OUT = join(ROOT, "apps/holtburger-web/scene3d/client_event_kinds.js");

const rs = readFileSync(SRC, "utf8");
const re = /^(?:pub(?:\(crate\))? )?const CLIENT_EVENT_KIND_([A-Z0-9_]+): u32 = (\d+);/gm;
const kinds = [];
const seen = new Map();
for (const m of rs.matchAll(re)) {
  const [, name, num] = m;
  const value = Number(num);
  if (seen.has(name)) {
    if (seen.get(name) !== value) {
      console.error(`CLIENT_EVENT_KIND_${name} declared twice with different values`);
      process.exit(1);
    }
    continue;
  }
  seen.set(name, value);
  kinds.push([name, value]);
}
if (kinds.length === 0) {
  console.error(`no CLIENT_EVENT_KIND_* constants found in ${SRC}`);
  process.exit(1);
}
kinds.sort((a, b) => a[1] - b[1] || a[0].localeCompare(b[0]));

const body =
  "// GENERATED by scripts/gen-client-event-kinds.mjs from the\n" +
  "// `CLIENT_EVENT_KIND_*` constants in src/lib.rs — do not edit by hand.\n" +
  "// Use these names instead of bare `evt.kind === N` numbers.\n\n" +
  "export const ClientEventKind = Object.freeze({\n" +
  kinds.map(([n, v]) => `  ${n}: ${v},`).join("\n") +
  "\n});\n";

if (process.argv.includes("--check")) {
  const cur = existsSync(OUT) ? readFileSync(OUT, "utf8") : "";
  if (cur !== body) {
    console.error(
      "scene3d/client_event_kinds.js is out of date with src/lib.rs — " +
        "run: node scripts/gen-client-event-kinds.mjs",
    );
    process.exit(1);
  }
  console.log(`client_event_kinds.js up to date (${kinds.length} kinds)`);
} else {
  writeFileSync(OUT, body);
  console.log(`wrote ${OUT} (${kinds.length} kinds)`);
}
